:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --text: #eaeaea;
  --muted: #9aa0b5;
  --track: #0f3460;
  --p1: #4ade80;
  --p2: #facc15;
  --focus: #ffd166;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  min-height: 100vh;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-card {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  max-width: 720px;
  width: 100%;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 1.6rem;
  margin: 0 0 4px;
  letter-spacing: 0.5px;
}

.subtitle {
  margin: 0 0 20px;
  color: var(--muted);
  font-size: 1rem;
}

.turn-indicator {
  font-size: 1.15rem;
  font-weight: 700;
  padding: 12px 16px;
  border-radius: 10px;
  background: var(--track);
  margin-bottom: 20px;
  transition: background 0.2s;
}

.turn-indicator.p1 { color: var(--p1); }
.turn-indicator.p2 { color: var(--p2); }

.track-wrapper {
  overflow-x: auto;
  padding: 8px 0;
  margin-bottom: 20px;
}

.track {
  display: grid;
  grid-template-columns: repeat(10, minmax(28px, 1fr));
  gap: 6px;
  min-width: 320px;
}

.square {
  position: relative;
  aspect-ratio: 1 / 1;
  background: var(--track);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  color: var(--muted);
  font-weight: 600;
  transition: transform 0.15s, background 0.15s;
}

.square.finish {
  background: var(--accent);
  color: #fff;
}

.square .token {
  position: absolute;
  width: 55%;
  height: 55%;
  border-radius: 3px;
  transition: all 0.2s ease;
}

.token.p1 {
  background: var(--p1);
  left: 8%;
  top: 8%;
  box-shadow: 0 0 0 2px rgba(0,0,0,0.3);
}

.token.p2 {
  background: var(--p2);
  right: 8%;
  bottom: 8%;
  box-shadow: 0 0 0 2px rgba(0,0,0,0.3);
}

.die-area {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: 16px;
}

.die {
  width: 64px;
  height: 64px;
  background: var(--text);
  color: var(--card);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  font-weight: 800;
  box-shadow: inset 0 -4px 0 rgba(0,0,0,0.2), 0 4px 12px rgba(0,0,0,0.3);
  transition: transform 0.15s;
}

.die.rolling {
  animation: shake 0.4s ease;
}

@keyframes shake {
  0%, 100% { transform: rotate(0deg); }
  25% { transform: rotate(-12deg) scale(1.05); }
  75% { transform: rotate(12deg) scale(1.05); }
}

.btn {
  font-family: inherit;
  font-size: 1.05rem;
  font-weight: 700;
  padding: 14px 28px;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
  min-width: 140px;
}

.btn.primary {
  background: var(--accent);
  color: #fff;
}

.btn.primary:hover:not(:disabled) {
  background: var(--accent-hover);
}

.btn.primary:active:not(:disabled) {
  transform: translateY(2px);
}

.btn.secondary {
  background: var(--track);
  color: var(--text);
}

.btn.secondary:hover:not(:disabled) {
  background: #1b4a7a;
}

.btn.secondary:active:not(:disabled) {
  transform: translateY(2px);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.status {
  min-height: 28px;
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--focus);
  margin-bottom: 12px;
}

.hint {
  margin: 0;
  font-size: 0.9rem;
  color: var(--muted);
}

kbd {
  background: var(--track);
  border-radius: 4px;
  padding: 2px 6px;
  font-family: inherit;
  font-size: 0.85rem;
}

@media (max-width: 480px) {
  .game-card { padding: 16px; }
  h1 { font-size: 1.35rem; }
  .track { gap: 4px; }
  .square { font-size: 0.65rem; border-radius: 4px; }
  .die { width: 52px; height: 52px; font-size: 1.6rem; }
  .btn { padding: 12px 20px; min-width: 120px; }
}

(function () {
  'use strict';

  const TOTAL_SQUARES = 20;
  const PLAYERS = ['Player 1', 'Player 2'];

  const trackEl = document.getElementById('track');
  const turnEl = document.getElementById('turn-indicator');
  const dieEl = document.getElementById('die');
  const rollBtn = document.getElementById('roll-btn');
  const playAgainBtn = document.getElementById('play-again-btn');
  const statusEl = document.getElementById('status');

  let state = createInitialState();

  function createInitialState() {
    return {
      positions: [0, 0],
      current: 0,
      gameOver: false,
      lastRoll: 1
    };
  }

  function buildTrack() {
    trackEl.innerHTML = '';
    for (let i = 1; i <= TOTAL_SQUARES; i++) {
      const square = document.createElement('div');
      square.className = 'square' + (i === TOTAL_SQUARES ? ' finish' : '');
      square.dataset.index = String(i);
      square.setAttribute('role', 'listitem');
      square.setAttribute('aria-label', 'Square ' + i + (i === TOTAL_SQUARES ? ', finish' : ''));
      square.textContent = i === TOTAL_SQUARES ? '20' : String(i);
      trackEl.appendChild(square);
    }
  }

  function renderTokens() {
    trackEl.querySelectorAll('.token').forEach(function (t) { t.remove(); });
    state.positions.forEach(function (pos, playerIndex) {
      if (pos <= 0) return;
      const square = trackEl.querySelector('.square[data-index="' + pos + '"]');
      if (!square) return;
      const token = document.createElement('span');
      token.className = 'token p' + (playerIndex + 1);
      token.setAttribute('aria-hidden', 'true');
      square.appendChild(token);
    });
  }

  function renderTurn() {
    if (state.gameOver) {
      turnEl.textContent = 'Game over';
      turnEl.className = 'turn-indicator';
      return;
    }
    turnEl.textContent = PLAYERS[state.current] + "'s turn";
    turnEl.className = 'turn-indicator p' + (state.current + 1);
  }

  function renderDie(value) {
    dieEl.textContent = String(value);
    dieEl.setAttribute('aria-label', 'Die showing ' + value);
  }

  function rollDie() {
    return Math.floor(Math.random() * 6) + 1;
  }

  function handleRoll() {
    if (state.gameOver) return;

    const value = rollDie();
    state.lastRoll = value;
    renderDie(value);

    dieEl.classList.remove('rolling');
    void dieEl.offsetWidth;
    dieEl.classList.add('rolling');

    const player = state.current;
    const oldPos = state.positions[player];
    const newPos = Math.min(oldPos + value, TOTAL_SQUARES);
    state.positions[player] = newPos;

    statusEl.textContent = PLAYERS[player] + ' rolled ' + value + ' and moved to square ' + newPos + '.';

    renderTokens();

    if (newPos >= TOTAL_SQUARES) {
      state.gameOver = true;
      statusEl.textContent = PLAYERS[player] + ' wins! 🎉';
      renderTurn();
      rollBtn.disabled = true;
      playAgainBtn.hidden = false;
      playAgainBtn.focus();
      return;
    }

    state.current = 1 - state.current;
    renderTurn();
  }

  function resetGame() {
    state = createInitialState();
    statusEl.textContent = '';
    renderDie(1);
    renderTokens();
    renderTurn();
    rollBtn.disabled = false;
    playAgainBtn.hidden = true;
    rollBtn.focus();
  }

  rollBtn.addEventListener('click', handleRoll);
  playAgainBtn.addEventListener('click', resetGame);

  document.addEventListener('keydown', function (event) {
    // Ignore key events when a button is focused (its native click handles it)
    if (event.target === rollBtn || event.target === playAgainBtn) return;
    if (event.code === 'Space' || event.key === 'Enter') {
      if (state.gameOver) {
        if (!playAgainBtn.hidden) {
          event.preventDefault();
          resetGame();
        }
      } else {
        event.preventDefault();
        handleRoll();
      }
    }
  });

  buildTrack();
  renderDie(1);
  renderTurn();
  renderTokens();
})();
